// dfs677: exhaustive search for finite magmas on {0..n-1} satisfying
//   E677:  x = y * (x * ((y * x) * y))
// that are generated by the element 0, in canonical labelling, optionally
// with E255 failing at 0 ("anti" mode, the default):  0 != ((0*0)*0)*0.
//
// Soundness of every rule is proved in AgenticConjectures/Etp677Implies255Finite.lean
// (see DETAILS.md):
//  * every row is a permutation (leftMul_bijective), so rows carry inverse maps;
//  * E677 is propagated along the chain a = y*x, b = a*y, c = x*b, y*c = x and
//    backwards via c' = L_y^{-1}(x), b' = L_x^{-1}(c'), using x*b = c' and
//    (y*x)*y = b' (inv_form, inv_form2);
//  * fixer uniqueness: y*x = x forces y = (x*x)*x (fixer_unique);
//  * anti mode: y*0 != 0, 0*(v*0) != v and 0*(y*y) != y for all y, v
//    (fixer_free_of_not255, ne_of_not255_v, ne_of_not255_vii);
//  * a countermodel yields one generated by a single non-E255 element
//    (exists_generated_countermodel), so only magmas generated by 0 are needed.
//
// Canonical labelling ("static phase", while some label is still missing):
// branch on the row-major-first unassigned cell (r,c) with r,c <= maxlabel,
// with values 0..maxlabel+1; the value maxlabel+1 creates the next label.  If
// [0..maxlabel]^2 is fully assigned, {0..maxlabel} is a closed proper
// submagma containing 0 and the branch is dead.  Each pointed magma (M,0)
// generated by 0 has exactly one such labelling.  Once all n labels exist
// ("dynamic phase") the cell with the smallest domain is chosen (sel 2: ties
// broken by the number of E677 chains blocked at the cell).
//
// usage: dfs677 n [general] [print] [sel 0|2] [split P p] [depth d] [split2 P2 p2]
//               [depth2 d2] [nofix] [novii]
//   split P p: at depth d (default 6) number the nodes in DFS order and explore
//   only those with index = p mod P; the P parts together cover the tree.
//   split2 P2 p2 subdivides a part the same way at depth d2 > d (default 10).
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <vector>
#include <chrono>

static const int MAXN = 31;
static int n;
static bool anti = true;
static bool printsol = false;
static int P = 1, pidx = 0, splitDepth = 6;
static int P2 = 1, pidx2 = 0, splitDepth2 = 10;
static int selKind = 0;
static bool useFix = true, useVii = true;

static int8_t T[MAXN][MAXN];    // table, -1 = unknown
static int8_t Inv[MAXN][MAXN];  // Inv[r][v] = column c with T[r][c] = v, -1 = none
static uint32_t dom[MAXN][MAXN];
static int maxlabel;

struct Tr { uint8_t kind, r, c; uint32_t old; };
static std::vector<Tr> trail;
static std::vector<uint16_t> q; static size_t qh;

static unsigned long long nodes = 0, sols = 0, snodes = 0, dnodes = 0;
static uint32_t FULL;

static inline int popc(uint32_t x){ return __builtin_popcount(x); }

static bool assign(int r, int c, int v);

static bool setdom(int r, int c, uint32_t nd) {
    if (nd == dom[r][c]) return true;
    trail.push_back({1, (uint8_t)r, (uint8_t)c, dom[r][c]});
    dom[r][c] = nd;
    if (nd == 0) return false;
    if (T[r][c] < 0 && (nd & (nd - 1)) == 0) {
        int v = __builtin_ctz(nd);
        if (v <= maxlabel && r <= maxlabel && c <= maxlabel) return assign(r, c, v);
    }
    return true;
}

static bool assign(int r, int c, int v) {
    if (T[r][c] >= 0) return T[r][c] == v;
    if (!((dom[r][c] >> v) & 1)) return false;
    if (Inv[r][v] >= 0) return false;
    T[r][c] = (int8_t)v; Inv[r][v] = (int8_t)c;
    trail.push_back({0, (uint8_t)r, (uint8_t)c, 0});
    q.push_back((uint16_t)(r * MAXN + c));
    if (dom[r][c] != (1u << v)) { trail.push_back({1, (uint8_t)r, (uint8_t)c, dom[r][c]}); dom[r][c] = 1u << v; }
    uint32_t bit = 1u << v;
    for (int j = 0; j < n; j++) {
        if (j == c || T[r][j] >= 0) continue;
        if (dom[r][j] & bit) { if (!setdom(r, j, dom[r][j] & ~bit)) return false; }
    }
    return true;
}

static void undo_to(size_t mark) {
    while (trail.size() > mark) {
        Tr t = trail.back(); trail.pop_back();
        if (t.kind == 0) { int v = T[t.r][t.c]; Inv[t.r][v] = -1; T[t.r][t.c] = -1; }
        else dom[t.r][t.c] = t.old;
    }
}

// constraint E(x,y): y*(x*((y*x)*y)) = x, i.e. chain
//   a = y*x, b = a*y, c = x*b, y*c = x.  Backward: c' = L_y^{-1}(x), b' = L_x^{-1}(c').
static bool eval(int x, int y) {
    int a = T[y][x];
    int cp = Inv[y][x];
    int bp = (cp >= 0) ? Inv[x][cp] : -1;
    if (a < 0) {
        if (bp >= 0) {
            // (y*x)*y = b': drop candidates a with a*y known and != b'
            uint32_t d = dom[y][x], nd = d;
            for (uint32_t m = d; m; m &= m - 1) {
                int aa = __builtin_ctz(m);
                if (aa > maxlabel) break;
                int t = T[aa][y];
                if (t >= 0 && t != bp) nd &= ~(1u << aa);
            }
            if (nd != d) return setdom(y, x, nd);
        }
        return true;
    }
    int b = T[a][y];
    if (b < 0) {
        if (bp >= 0) return assign(a, y, bp);
        if (cp >= 0) {
            // need x*b = cp where cp not yet in row x: b must be an unassigned column of row x
            uint32_t d = dom[a][y], nd = d;
            for (uint32_t m = d; m; m &= m - 1) {
                int bb = __builtin_ctz(m);
                if (bb > maxlabel) break;
                if (T[x][bb] >= 0 || !((dom[x][bb] >> cp) & 1)) nd &= ~(1u << bb);
            }
            if (nd != d) return setdom(a, y, nd);
        }
        return true;
    }
    int c = T[x][b];
    if (c < 0) {
        if (cp >= 0) return assign(x, b, cp);
        // need y*c = x where x not yet in row y: c must be an unassigned column of row y
        uint32_t d = dom[x][b], nd = d;
        for (uint32_t m = d; m; m &= m - 1) {
            int c2 = __builtin_ctz(m);
            if (c2 > maxlabel) break;
            if (T[y][c2] >= 0 || !((dom[y][c2] >> x) & 1)) nd &= ~(1u << c2);
        }
        if (nd != d) return setdom(x, b, nd);
        return true;
    }
    int d = T[y][c];
    if (d < 0) return assign(y, c, x);
    return d == x;
}

static bool propagate() {
    while (qh < q.size()) {
        int r = q[qh] / MAXN, c = q[qh] % MAXN; qh++;
        int v = T[r][c];
        if (anti) {
            // 0*(w*0) != w.  Cell (w,0)=u forbids 0*u = w; cell (0,u)=w forbids w*0 = u.
            if (c == 0) {
                int u = v, w = r;
                if (T[0][u] >= 0) { if (T[0][u] == w) return false; }
                else if ((dom[0][u] >> w) & 1) { if (!setdom(0, u, dom[0][u] & ~(1u << w))) return false; }
            }
            if (r == 0) {
                int u = c, w = v;
                if (T[w][0] >= 0) { if (T[w][0] == u) return false; }
                else if ((dom[w][0] >> u) & 1) { if (!setdom(w, 0, dom[w][0] & ~(1u << u))) return false; }
            }
        }
        if (useFix) {
            // F1: r is a fixer of c (r*c = c): no other fixer; and (c*c)*c = r
            if (v == c) {
                for (int y2 = 0; y2 < n; y2++) if (y2 != r) {
                    if (T[y2][c] == c) return false;
                    if (T[y2][c] < 0 && ((dom[y2][c] >> c) & 1)) { if (!setdom(y2, c, dom[y2][c] & ~(1u << c))) return false; }
                }
                int s = T[c][c];
                if (s >= 0 && !assign(s, c, r)) return false;
            }
            // F2: (x*x)*x known -> only it may fix x
            int xx = -1;
            if (r == c) xx = r;                       // diagonal assigned
            else if (T[c][c] == r) xx = c;            // cell (x*x, x) assigned
            if (xx >= 0) {
                int s = T[xx][xx]; int f = (s >= 0) ? T[s][xx] : -1;
                if (f >= 0) {
                    for (int y2 = 0; y2 < n; y2++) if (y2 != f) {
                        if (T[y2][xx] == xx) return false;
                        if (T[y2][xx] < 0 && ((dom[y2][xx] >> xx) & 1)) { if (!setdom(y2, xx, dom[y2][xx] & ~(1u << xx))) return false; }
                    }
                }
            }
        }
        if (anti && useVii) {
            // 0*(y*y) != y
            if (r == c) { int s = v, y = r;
                if (T[0][s] >= 0) { if (T[0][s] == y) return false; }
                else if ((dom[0][s] >> y) & 1) { if (!setdom(0, s, dom[0][s] & ~(1u << y))) return false; } }
            if (r == 0) { int s = c, y = v;
                if (T[y][y] >= 0) { if (T[y][y] == s) return false; }
                else if ((dom[y][y] >> s) & 1) { if (!setdom(y, y, dom[y][y] & ~(1u << s))) return false; } }
        }
        for (int x = 0; x <= maxlabel; x++) {
            if (!eval(x, r)) return false;
            if (c != r && !eval(x, c)) return false;
        }
        for (int y = 0; y <= maxlabel; y++) if (!eval(r, y)) return false;
    }
    return true;
}

// hidden singles on rows (only valid once all labels exist)
static bool hidden() {
    if (maxlabel < n - 1) return true;
    bool changed = true;
    while (changed) {
        changed = false;
        for (int r = 0; r < n; r++) {
            uint32_t have = 0, once = 0, twice = 0;
            for (int c = 0; c < n; c++) {
                if (T[r][c] >= 0) { have |= 1u << T[r][c]; continue; }
                uint32_t d = dom[r][c];
                twice |= once & d; once |= d;
            }
            uint32_t missing = FULL & ~have;
            if (missing & ~once) return false;
            uint32_t singles = missing & once & ~twice;
            while (singles) {
                int v = __builtin_ctz(singles); singles &= singles - 1;
                for (int c = 0; c < n; c++) if (T[r][c] < 0 && ((dom[r][c] >> v) & 1)) {
                    if (!assign(r, c, v)) return false;
                    if (!propagate()) return false;
                    changed = true; break;
                }
            }
        }
    }
    return true;
}

// independent check of a complete table
static bool verify() {
    for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) {
        if (T[x][y] < 0) return false;
    }
    for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) {
        if (T[y][T[x][T[T[y][x]][y]]] != x) return false;
    }
    if (anti && T[T[T[0][0]][0]][0] == 0) return false;
    return true;
}

static void report() {
    if (!verify()) { fprintf(stderr, "INTERNAL ERROR: leaf fails verification\n"); exit(3); }
    sols++;
    if (printsol) {
        printf("SOL");
        for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) printf(" %d", T[x][y]);
        printf("\n"); fflush(stdout);
    }
}

static int depth = 0;
static unsigned long long splitCounter = 0, splitCounter2 = 0;

static void search() {
    nodes++;
    int br = -1, bc = -1;
    uint32_t bdom = 0;
    if (maxlabel < n - 1) {
        snodes++;
        // canonical labelling: row-major-first unassigned cell among existing labels
        for (int r = 0; r <= maxlabel && br < 0; r++) for (int c = 0; c <= maxlabel; c++)
            if (T[r][c] < 0) { br = r; bc = c; break; }
        if (br < 0) return;   // {0..maxlabel} closed: not generated by 0
        uint32_t lim = (maxlabel + 2 >= 32) ? 0xffffffffu : ((1u << (maxlabel + 2)) - 1);
        bdom = dom[br][bc] & lim & FULL;
    } else {
        dnodes++;
        if (selKind == 0) {
            int best = 99;
            for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) if (T[r][c] < 0) {
                int p = popc(dom[r][c]);
                if (p < best) { best = p; br = r; bc = c; if (p <= 1) goto found; }
            }
        } else {
            static int score[MAXN][MAXN];
            for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) score[r][c] = 0;
            for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) {
                int a = T[y][x]; if (a < 0) { score[y][x] += 2; continue; }
                int b = T[a][y]; if (b < 0) { score[a][y] += 3; continue; }
                int c2 = T[x][b]; if (c2 < 0) { score[x][b] += 4; continue; }
            }
            long best = -1000000;
            for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) if (T[r][c] < 0) {
                int p = popc(dom[r][c]);
                long sc = -(long)p * 1000 + score[r][c];
                if (sc > best) { best = sc; br = r; bc = c; }
            }
        }
        found:
        if (br < 0) { report(); return; }
        bdom = dom[br][bc];
    }
    if (depth == splitDepth && P > 1) {
        unsigned long long id = splitCounter++;
        if ((int)(id % P) != pidx) return;
    }
    if (depth == splitDepth2 && P2 > 1) {
        unsigned long long id = splitCounter2++;
        if ((int)(id % P2) != pidx2) return;
    }
    for (uint32_t m = bdom; m; m &= m - 1) {
        int v = __builtin_ctz(m);
        size_t mark = trail.size();
        int savedMax = maxlabel;
        if (v == maxlabel + 1) maxlabel = v;
        q.clear(); qh = 0;
        bool ok = assign(br, bc, v) && propagate() && hidden();
        if (ok) { depth++; search(); depth--; }
        undo_to(mark);
        maxlabel = savedMax;
    }
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: dfs677 n [general] [print] [sel 0|2] [split P p] [depth d] [split2 P2 p2] [depth2 d2] [nofix] [novii]\n"); return 1; }
    n = atoi(argv[1]);
    if (n < 1 || n > MAXN) { fprintf(stderr, "n must be in 1..%d\n", MAXN); return 1; }
    for (int i = 2; i < argc; i++) {
        if (!strcmp(argv[i], "general")) anti = false;
        else if (!strcmp(argv[i], "print")) printsol = true;
        else if (!strcmp(argv[i], "split")) { P = atoi(argv[++i]); pidx = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "depth")) splitDepth = atoi(argv[++i]);
        else if (!strcmp(argv[i], "split2")) { P2 = atoi(argv[++i]); pidx2 = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "depth2")) splitDepth2 = atoi(argv[++i]);
        else if (!strcmp(argv[i], "sel")) selKind = atoi(argv[++i]);
        else if (!strcmp(argv[i], "nofix")) useFix = false;
        else if (!strcmp(argv[i], "novii")) useVii = false;
        else { fprintf(stderr, "unknown option %s\n", argv[i]); return 1; }
    }
    FULL = (n >= 32) ? 0xffffffffu : ((1u << n) - 1);
    memset(T, -1, sizeof T); memset(Inv, -1, sizeof Inv);
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) dom[i][j] = FULL;
    if (anti) for (int y = 0; y < n; y++) dom[y][0] &= ~1u; // y*0 != 0
    maxlabel = 0;
    trail.reserve(1 << 20);
    auto t0 = std::chrono::steady_clock::now();
    search();
    double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
    printf("RESULT n=%d mode=%s split=%d/%d split2=%d/%d nodes=%llu (static %llu dyn %llu) solutions=%llu time=%.2fs\n",
           n, anti ? "anti255" : "general", pidx, P, pidx2, P2, nodes, snodes, dnodes, sols, secs);
    return 0;
}
